// ---------- helpers ----------
const pt=(r,i)=>(r.tt&&r.tt[i])||tm(r.t,OFF[i]-OFF[r.pts[0]]||0);
const tm=(s,i,raw)=>{let[h,m]=String(s||'7:30').split(':').map(Number);m+=raw?i:(OFF[i]||0);h+=Math.floor(m/60);m=((m%60)+60)%60;return h+':'+String(m).padStart(2,'0')};
const mn=s=>{const a=String(s||'0:0').split(':').map(Number);return a[0]*60+a[1]};
const comm=p=>Math.round(p*.15);
const norm=v=>String(v||'').replace(/^0(?=\d:)/,'');
const dayStr=d=>!d||d.length===7?'كل يوم':d.map(i=>DN[i]).join('، ');
const ago=t=>{const m=Math.round((Date.now()-new Date(t).getTime())/60000);return m<1?'دلوقتي':m<60?'من '+m+' دقيقة':m<1440?'من '+Math.round(m/60)+' ساعة':'من '+Math.round(m/1440)+' يوم'};
const fm=m=>m<60?m+' دقيقة':Math.floor(m/60)+' ساعة'+(m%60?' و'+m%60+' دقيقة':'');
const fv=id=>(S.fv||[]).includes(id);
function toast(t){const e=$('toast');try{navigator.vibrate&&navigator.vibrate(30)}catch(x){}e.textContent=t;e.style.display='block';clearTimeout(toast.i);toast.i=setTimeout(()=>e.style.display='none',3000)}
function ntf(t){S.nt=S.nt||[];if(S.nt[0]&&S.nt[0].t===t)return;S.nt.unshift({t,at:Date.now(),r:0});S.nt=S.nt.slice(0,30);save();bell()}
function bell(){const c=(S.nt||[]).filter(x=>!x.r).length,e=$('bdg');if(!e)return;e.hidden=!c;e.textContent=c}
function nsh(){const n=S.nt||[];closeBk();$('bk').innerHTML=`<div class="card"><div class="row"><b>الإشعارات</b><button class="btn g" style="min-height:36px" onclick="closeBk()">إغلاق</button></div>${n.length?n.map(x=>`<div class="tl"><i></i><div>${esc(x.t)}<div class="mu">${ago(x.at)}</div></div></div>`).join(''):'<span class="mu">مفيش إشعارات لسه.</span>'}</div>`;n.forEach(x=>x.r=1);save();bell()}
function closeBk(){wo=false;bk=null;bp=null;$('bk').innerHTML=''}
function tab(n){if(n===6&&!IS_ADMIN)n=1;for(let i=1;i<=6;i++){const v=$('v'+i),b=$('n'+i);if(!v||!b)continue;v.hidden=i!==n;b.setAttribute('aria-selected',i===n)}hl(n===3&&S.trip?S.trip.rt:n===2?+$('rt').value:null);extra();if(n===6)admLoad()}
