const GMD=(a,b)=>`https://www.google.com/maps?saddr=${encodeURIComponent(a)}&daddr=${encodeURIComponent(b)}&hl=${UI_LANG}&output=embed`;
function map(){$('mapw').innerHTML=`<iframe title="خريطة جوجل للطريق" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="${GM('القاهرة الكبرى، مصر',9)}"></iframe>`}
function mapSel(){const el=$('mapw');if(!el)return;const fr=el.querySelector('iframe');if(!fr)return;const f=$('f').value,d=$('df').value;
fr.src=(f===''&&d==='')?GM('القاهرة الكبرى، مصر',9):(f===''||d==='')?GM(f!==''?qp(f):d!==''?qd(d):'القاهرة الكبرى، مصر',f!==''||d!==''?13:9):GMD(qp(f),qd(d))}
// ---------- data loading ----------
async function loadPoints(){
  try{
    const[{data:base},{data:cps}]=await Promise.all([
      sb.from('points').select('kind,id,name,off_minutes,km').order('id'),
      sb.from('custom_points').select('id,name,off_minutes,km').order('id')]);
    if(base&&base.length){
      PTS=[];OFF=[];KM=[];DROP=[];
      base.forEach(p=>{if(p.kind==='pickup'){PTS[p.id]=p.name;OFF[p.id]=p.off_minutes||0;KM[p.id]=+p.km||0}else DROP[p.id]=p.name});addAreas();
    }
    try{const {data:catalog}=await sb.from('meeting_catalog').select('area_index,points').order('area_index');if(catalog)catalog.forEach(c=>{if(MPS[c.area_index]&&Array.isArray(c.points)&&c.points.length>=MPS[c.area_index].length&&c.points.length<100)MPS[c.area_index]=c.points})}catch(e){}
    addMPS();
    (cps||[]).forEach(c=>{PTS[c.id]=c.name;OFF[c.id]=c.off_minutes;KM[c.id]=+c.km||0});
  }catch(e){}
}
function adaptRide(r){return{id:r.id,r:r.route,t:r.t,tt:r.tt||{},pts:r.pts||[],dr:r.dr,seats:r.seats,left:r.left,price:r.price,car:r.car,col:r.col,pl:r.plate,who:r.who||(NAMES[r.driver_id]||'سواق'),w:r.women,days:r.days,vb:r.vb||[],ar:r.ar,mine:r.driver_id===ME,demo:r.is_demo,driver:r.driver_id,st:r.status}}
async function loadNames(ids){ids=[...new Set(ids.filter(Boolean))];if(!ids.length)return;
  const{data}=await sb.from('profiles').select('id,name').in('id',ids);
  (data||[]).forEach(p=>{NAMES[p.id]=p.name});
  ids.forEach(id=>{delete VFD[id];delete RT_SUM[id]});
  try{const{data:dv,error}=await sb.from('driver_verification_status').select('driver_id,status').in('driver_id',ids).eq('status','approved');if(!error)(dv||[]).forEach(x=>{if(x.status==='approved')VFD[x.driver_id]='approved'})}catch(e){}
  try{const{data:rs}=await sb.from('driver_ratings_summary').select('driver_id,avg,count').in('driver_id',ids);(rs||[]).forEach(x=>RT_SUM[x.driver_id]=x)}catch(e){}}
async function refreshRides(){
  const{data}=await sb.from('rides').select('*').in('status',['open','active']).order('created_at',{ascending:false}).limit(100);
  if(!data)return;
  await loadNames(data.map(r=>r.driver_id));
  RIDES=data.map(adaptRide).filter(r=>R[r.r]&&DROP[r.dr||0]&&Array.isArray(r.pts)&&r.pts.length&&r.pts.every(p=>PTS[p]));MYRIDES=RIDES.filter(r=>r.mine);
}
function adaptBooking(b){const r=b.ride||{};return{bid:b.id,rid:b.ride_id,p:b.pt,t:(r.tt&&r.tt[b.pt])||tm(r.t,(OFF[b.pt]||0)-(OFF[(r.pts||[0])[0]]||0)),dr:r.dr||0,price:b.price,offer:b.offer,rt:r.route||0,car:r.car||'',col:r.col||'',pl:r.plate||'',who:r.who||'السواق',wk:b.weekly?1:0,pin:b.pin,st:b.status,arrv:b.arrived_at||null,rst:r.status||'',stars:b.stars,tags:b.tags||[],at:new Date(b.created_at).getTime(),driver:r.driver_id,ride:r.id?adaptRide(r):null,days:r.days}}
async function refreshMyBooks(notify){
  const{data}=await sb.from('bookings').select('*,ride:rides(*)').eq('passenger_id',ME).order('created_at',{ascending:false}).limit(60);
  if(!data)return;
  const old={};MYBOOKS.forEach(b=>old[b.bid]={st:b.st,arrv:b.arrv,rst:b.rst});
  MYBOOKS=data.map(adaptBooking).filter(b=>R[b.rt]&&PTS[b.p]&&b.price!=null);
  if(notify)MYBOOKS.forEach(b=>{const o=old[b.bid];if(!o)return;
    if(o.st!==b.st){
      if(b.st==='accepted')ntf('السواق وافق على عرضك · '+b.price+' جنيه');
      else if(b.st==='countered')ntf('السواق رد بسعر '+b.price+' جنيه');
      else if(b.st==='onboard')ntf('السواق أكد إنك ركبت. رحلة سعيدة');
      else if(b.st==='cancelled'&&o.st!=='cancelled')ntf('اتلغى حجزك في مشوار '+R[b.rt].n)}
    if(!o.arrv&&b.arrv&&b.st==='accepted')ntf('السواق وصل لنقطتك · مشوار '+R[b.rt].n);
    if(o.rst&&o.rst!==b.rst&&b.rst==='active'&&['accepted','onboard'].includes(b.st))ntf('رحلتك بدأت · مشوار '+R[b.rt].n+' على الطريق')});
}
async function refreshPax(notify){
  if(!MYRIDES.length){PAX={};return}
  const{data}=await sb.from('bookings').select('*').in('ride_id',MYRIDES.map(r=>r.id)).in('status',['pending','countered','accepted','onboard']).order('created_at');
  if(!data)return;
  await loadNames(data.map(b=>b.passenger_id));
  const old=PAX;PAX={};data.forEach(b=>{(PAX[b.ride_id]=PAX[b.ride_id]||[]).push(b)});
  if(notify)data.forEach(b=>{const prev=(old[b.ride_id]||[]).find(x=>x.id===b.id);
    if(!prev&&b.status==='pending')ntf('عرض حجز جديد على مشوارك: '+b.price+' جنيه');
    if(!prev&&b.status==='accepted')ntf('مقعد اتحجز في مشوارك: '+b.price+' جنيه');
    if(prev&&prev.status!==b.status&&b.status==='accepted'&&prev.status==='countered')ntf('الراكب قبل سعرك '+b.price+' جنيه')});
}
