async function renderTrip(){const t=S.trip,e=$('trip');
if(!t){e.innerHTML=hub();return}
const live=MYBOOKS.find(x=>x.bid===t.bid);
if(live&&live.st==='cancelled'){S.trip=null;save();e.innerHTML=hub();return}
if(live){t.price=live.price;t.pin=live.pin;t.who=live.who;t.car=live.car;t.col=live.col;t.pl=live.pl;t.ride=live.ride}
return trip2(t,e)}
function geo(t){const S0=stops(t),n=S0.length,ui=Math.max(0,S0.findIndex(x=>x.i===t.p)),now=Date.now(),fk=k=>.1+.75*k/Math.max(1,n-1),pf=fk(ui);
const pr=t.st==='c'?pf*Math.min(1,(now-t.at)/(6000*(ui+1))):t.st==='o'?pf+(1-pf)*Math.min(1,(now-(t.ob||now))/(8000*(n-ui))):1;
return{S0,n,ui,fk,pf,pr,cur:S0.reduce((a,x,k)=>fk(k)<=pr+1e-9?k:a,0)}}
function tmap(t){
return `<iframe title="خريطة جوجل للرحلة" loading="lazy" referrerpolicy="no-referrer-when-downgrade" style="width:100%;height:320px;border:0;display:block;border-radius:18px;background:#EAE6DA" src="${GMD(qp(t.p),qd(t.dr||0))}"></iframe>`}
