const eta=t.st==='c'&&!arr?Math.max(1,Math.ceil((1-g.pr/g.pf)*8)):t.st==='o'?Math.max(1,Math.ceil((1-g.pr)*(g.n-g.ui)*2)):0,pg=t.st==='c'?g.pr/g.pf:t.st==='o'?(g.pr-g.pf)/(1-g.pf):1;
$('tban').className='ban b'+k;$('tban').innerHTML=`<div><small>${['','في الطريق ليك',arr?'وصل! هيستنى 3:00':'وصل!','رحلتك شغالة','خلصت'][k]}</small><b>${['','السواق جاي لنقطتك','السواق وصل '+PTS[t.p],'في الطريق لـ '+DROP[t.dr||0],'وصلت بالسلامة'][k]}</b></div><svg class="ring" width="64" height="64" viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="26" fill="none" stroke="rgba(255,255,255,.3)" stroke-width="6"/><circle cx="32" cy="32" r="26" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" stroke-dasharray="${163.4*Math.min(1,Math.max(0,pg))} 163.4" transform="rotate(-90 32 32)"/><text x="32" y="38" text-anchor="middle">${k===4?'✓':eta?eta+'د':'●'}</text></svg>`;
