function rqd(){const L=RQS;return `<div class="card"><b>طلبات ركاب (${L.length})</b><span class="mu">ركاب مستنيين مشوار على طريقك. اضغط وانشر مشوارك بسرعة.</span>${L.length?L.map(x=>`<div class="row"><div><b style="font-weight:400">${PTS[x.p]} ← ${DROP[x.d]}</b><div class="mu">${x.t} · ${esc(x.who||'راكب')}</div></div>${x.user_id===ME?'<span class="chip">طلبك</span>':`<button class="btn" style="min-height:36px" onclick="fillRq(${x.id})">عندي مشوار</button>`}</div>`).join(''):'<span class="mu">مفيش طلبات دلوقتي.</span>'}</div>`}
function fillRq(id){const x=RQS.find(y=>y.id===id);if(!x)return;tab(2);if($('v2').classList.contains('cl'))tg2();document.querySelectorAll('.pp').forEach(e=>e.checked=+e.value===x.p);$('dr').value=x.d;$('time').value=x.t.padStart(5,'0');man={};ttRender();ps=1;psr();toast('جهزنالك المشوار. اكتب بيانات عربيتك وكمّل.')}

// ---------- pickers / custom points ----------
function ord(){const k=i=>i>=100?[1,i]:[0,OFF[i]||0];return PTS.map((n,i)=>i).filter(i=>PTS[i]).sort((a,b)=>{const x=k(a),y=k(b);return x[0]-y[0]||x[1]-y[1]})}
const og=()=>[['الجيزة',i=>(GOV[DROP[dArea(i)]]||'الجيزة')==='الجيزة'],['القاهرة',i=>GOV[DROP[dArea(i)]]==='القاهرة']].map(g=>`<optgroup label="${g[0]}">`+DROP.map((p,i)=>[p,i]).filter(x=>x[0]&&g[1](x[1])).map(x=>`<option value="${x[1]}">${x[0]}</option>`).join('')+'</optgroup>').join('');
function pkt(){const a=$('f').value,b=$('df').value,ch='<svg viewBox="0 0 24 24" width="16" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 9l6 6 6-6"/></svg>';
const auto=a!==''&&S.geoF===+a;
$('pk1').innerHTML='<span>'+(a===''?'كل النقاط':pl1(+a))+(auto?' <i class="au">· تلقائي</i>':'')+'</span>'+ch;
$('pk2').innerHTML=(b===''?'<span class="w2ph">رايح فين؟</span>':'<span class="w2sel">'+pl2(+b)+'</span>')+'<span class="w2ic"><svg viewBox="0 0 24 24" width="20" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/></svg></span>';promoR();quickPlaces()}
function promoR(){if($('promo').children.length)return;const P=[['linear-gradient(135deg,#C2410C,#9A3412)','وفّر 10% باشتراك أسبوعي','احجز مرة وامشي 5 أيام','tab(1)'],['linear-gradient(135deg,#2563EB,#1E3A8A)','ادعي صاحبك','شاركه اللينك وخليه يجرب','tab(5)'],['linear-gradient(135deg,#7C3AED,#4C1D95)','كون سواق موثّق','وثّق حسابك وخد شارة وحجوزات أكتر','tab(2)'],['linear-gradient(135deg,#0F766E,#0B4F4A)','مش لاقي مشوار؟','اطلب مشوارك والسواقين هيشوفوه','rqf()']];$('promo').innerHTML=P.map(x=>`<button class="pc" style="background:${x[0]}" onclick="${x[3]}"><b>${x[1]}</b><span>${x[2]}</span></button>`).join('')}
let PK_CAT='all',PK_AREA=null;
const PK_CATS=[['all','كل الأماكن'],['metro','مترو ومواصلات'],['university','جامعات'],['hospital','مستشفيات'],['shopping','مولات'],['landmark','معالم']];
function pkType(n){return /مترو|محطة|موقف|صالة.*مطار/.test(n)?'metro':/مستشف|مستشفي|هوسبيتال|هوسبيتل|مركز.*طب|طب[يى]|عيادات/.test(n)?'hospital':/جامعة|جامع[ةه]|كلية|أكاديمية/.test(n)?'university':/مول|بلازا|سكوير|ستريب|سيتي سنتر|سنترادا|جاليريا|كورت يارد|أركان|بارك ستريت|سوق|سنترال بارك|إيست هب|أوبن إير|كرافت زون|أول سيزونز|ووتر واي/.test(n)?'shopping':'landmark'}
function pkChips(k,a){return '<div class="pkchips" role="group" aria-label="نوع المكان">'+PK_CATS.map(c=>`<button class="pkchip" aria-pressed="${PK_CAT===c[0]}" onclick="PK_CAT='${c[0]}';${a===undefined?'pkl('+k+')':'pkmList('+k+','+a+')'}">${c[1]}</button>`).join('')+'</div>'}
function pkFits(n,q){return n&&uiPlaceMatch(n,q)&&(PK_CAT==='all'||pkType(n)===PK_CAT)}
function pkSaved(k,i){return (S.sp||[]).some(p=>p.k===k&&p.i===+i)}
function pkSave(k,i){const L=k===1?PTS:DROP;if(!L[i])return;const found=pkSaved(k,i);S.sp=S.sp||[];if(found)S.sp=S.sp.filter(p=>!(p.k===k&&p.i===+i));else{if(S.sp.length>=16)return toast('تقدر تحفظ ١٦ مكان. شيل مكان قديم الأول.');S.sp.push({k,i:+i})}save();quickPlaces();if(PK_AREA===null)pkl(k);else pkmList(k,PK_AREA);toast(found?'اتشال من المحفوظة':'اتحفظ على الجهاز ده بس')}
function quickPlaces(){let e=$('qplaces');if(!e){e=document.createElement('div');e.id='qplaces';document.querySelector('.hero').append(e)}const ps=(S.sp||[]).filter(p=>p.k===2&&DROP[p.i]);e.hidden=!ps.length;routeToolsRender();e.innerHTML=ps.length?'<span class="qptitle">وجهاتك السريعة</span><div class="qpbuttons">'+ps.slice(0,4).map(p=>`<button onclick="pks(2,${p.i},1)">${uiIcon('star')}<span>${esc(DROP[p.i])}</span></button>`).join('')+'</div>':''}
function validRoute(f,d){const ok=(v,L)=>v===''||(Number.isSafeInteger(+v)&&String(+v)===String(v)&&!!L[+v]);return ok(f,PTS)&&ok(d,DROP)}
function routeSelect(k,i){const e=$(k===1?'f':'df'),L=k===1?PTS:DROP;if(i!==''&&!e.querySelector('option[value="'+i+'"]')){const o=document.createElement('option');o.value=i;o.textContent=L[i];e.appendChild(o)}e.value=i}
function rememberRoute(){const f=$('f').value,d=$('df').value;if(!f||!d||!validRoute(f,d))return;S.rh=[{f:+f,d:+d,at:Date.now()},...(S.rh||[]).filter(x=>String(x.f)!==f||String(x.d)!==d)].slice(0,5)}
function routeSet(f,d,keep=true){f=f===''?'':+f;d=d===''?'':+d;if(!validRoute(f,d))return toast('المكان ده مش موجود في القايمة الحالية.');GEO_MANUAL_AT=Date.now();delete S.geoF;routeSelect(1,f);routeSelect(2,d);if(keep)rememberRoute();save();closeBk();skl();pkt()}
function mirrorPoint(i,k){const L=k===1?PTS:DROP,PAR=k===1?PAR_P:PAR_D,base=k===1?100:29;if(i>=base&&i<base+126)return (k===1?29:100)+(i-base);const parent=PAR[i];if(parent===undefined)return null;const a=parent-base,j=(MPS[a]||[]).findIndex((p,j)=>mpid(a,j,k)===+i);if(j>=0)return mpid(a,j,k===1?2:1);const byName=(MPS[a]||[]).findIndex(p=>p[0]===L[i]);return byName<0?null:mpid(a,byName,k===1?2:1)}
function routeSwap(){const f=$('f').value,d=$('df').value;if(f===''||d==='')return toast('اختار نقطة الركوب والوصول الأول.');const nf=mirrorPoint(+d,2),nd=mirrorPoint(+f,1);if(nf===null||nd===null)return toast('النقطة دي ملهاش مقابل دقيق للرجوع. اختارها بنفسك عشان ما نغيرش مكانك.');routeSet(nf,nd);toast('اتبدّل اتجاه البحث. الحجز مش بيتغير.')}
function routeBroaden(){const f=$('f').value,d=$('df').value;const nf=f===''?'':pArea(+f),nd=d===''?'':dArea(+d);if(String(nf)===f&&String(nd)===d)return toast('البحث بالفعل على مستوى المنطقة.');routeSet(nf,nd);toast('بنبحث في كل المنطقة بدل النقطة المحددة.')}
async function routeShare(){const f=$('f').value,d=$('df').value;if(f===''&&d==='')return toast('اختار وجهتك أو نقطة الركوب الأول.');const u=new URL(location.origin+location.pathname);if(f!=='')u.searchParams.set('from',f);if(d!=='')u.searchParams.set('to',d);try{await navigator.clipboard.writeText(u.href);toast('اتنسخ رابط البحث. تقدر تبعته بنفسك.')}catch(e){$('bk').innerHTML=`<div class="card pkcard"><div class="row"><b>رابط البحث</b><button class="btn g" onclick="closeBk()">إغلاق</button></div><p class="mu">الرابط فيه الأماكن المختارة بس، من غير حسابك أو بياناتك. انسخه وابعته بنفسك.</p><input readonly dir="ltr" aria-label="رابط البحث" value="${esc(u.href)}" onclick="this.select()"></div>`}}
function routeFromLink(){const q=new URLSearchParams(location.search);if(!q.has('from')&&!q.has('to'))return;const f=q.get('from')||'',d=q.get('to')||'';if(!validRoute(f,d))return toast('رابط البحث فيه مكان غير معروف. اختار المكان من القايمة.');routeSet(f,d)}
function routeToolsRender(){let e=$('rtbar');if(!e){e=document.createElement('div');e.id='rtbar';document.querySelector('.hero').append(e)}const chosen=$('f').value!==''||$('df').value!=='',hist=(S.rh||[]).filter(x=>validRoute(x.f,x.d));e.hidden=!chosen&&!hist.length;e.innerHTML=(chosen?'<button onclick="routeTools()">'+uiIcon('route')+'<span>أدوات البحث</span></button>':'')+(hist.length?'<button onclick="routeHistory()">'+uiIcon('clock')+'<span>مشاوير بحثت عنها</span></button>':'')}
function routeTools(){const both=$('f').value!==''&&$('df').value!=='';$('bk').innerHTML=`<div class="card pkcard"><div class="row"><h2>أسهل في كل مرة</h2><button class="btn g" onclick="closeBk()">إغلاق</button></div><p class="mu">دي أدوات للبحث بس. مفيش حجز أو دفع تلقائي.</p><button class="pp2 pkplace" onclick="routeSwap()" ${both?'':'disabled'}><span class="pkplaceicon">${uiIcon('route')}</span><span class="pkplacetext"><b>بدّل اتجاه الرحلة</b><span class="mu">للرجوع بنفس نقط الركوب والوصول</span></span></button><button class="pp2 pkplace" onclick="routeShare()"><span class="pkplaceicon">${uiIcon('arrow')}</span><span class="pkplacetext"><b>انسخ رابط البحث</b><span class="mu">الأماكن المختارة بس، من غير بيانات حسابك</span></span></button><button class="pp2 pkplace" onclick="routeBroaden()"><span class="pkplaceicon">${uiIcon('search')}</span><span class="pkplacetext"><b>وسّع البحث لكل المنطقة</b><span class="mu">شوف نقط تانية بدل نقطة واحدة</span></span></button></div>`}
function routeHistory(clear){const list=(S.rh||[]).filter(x=>validRoute(x.f,x.d));$('bk').innerHTML=`<div class="card pkcard"><div class="row"><h2>مشاوير بحثت عنها</h2><button class="btn g" onclick="closeBk()">إغلاق</button></div><p class="mu">آخر ٥ مسارات على الجهاز ده بس. الاختيار بيعيد البحث، مش بيحجز.</p>${clear?'<p>تمسح سجل البحث من الجهاز ده؟</p><button class="btn" onclick="S.rh=[];save();routeToolsRender();routeHistory()">أيوه، امسح السجل</button><button class="btn g" onclick="routeHistory()">رجوع</button>':list.map(x=>`<button class="pp2 pkplace" onclick="routeSet(${x.f},${x.d})"><span class="pkplaceicon">${uiIcon('clock')}</span><span class="pkplacetext"><b>${esc(pl1(x.f))}</b><span class="mu">إلى ${esc(pl2(x.d))}</span></span></button>`).join('')+(list.length?'<button class="btn g" onclick="routeHistory(true)">مسح سجل البحث</button>':'<span class="mu">لسه مفيش مسارات محفوظة.</span>')}</div>`}
function pkRow(k,i,t,sub,skip){const cur=$(k===1?'f':'df').value,on=pkSaved(k,i);return `<div class="pkline"><button class="pp2 pkplace" aria-pressed="${String(i)===cur}" onclick="pks(${k},'${i}',${skip||0})"><span class="pkplaceicon">${uiIcon(pkType(t)==='metro'?'route':pkType(t)==='university'?'user':pkType(t)==='hospital'?'plus':'pin')}</span><span class="pkplacetext"><b>${esc(t)}</b>${sub?`<span class="mu">${esc(sub)}</span>`:''}</span><span class="tick"></span></button><button class="pkstar" type="button" aria-pressed="${on}" aria-label="${on?'إزالة من المحفوظة':'حفظ المكان'}" title="${on?'إزالة من المحفوظة':'حفظ المكان'}" onclick="pkSave(${k},${i})">${uiIcon('star')}</button></div>`}
function pkr(k){bk=null;PK_CAT='all';PK_AREA=null;$('bk').innerHTML=`<div class="card pkcard"><div class="row"><div><span class="pkcaption">اختار المكان اللي يناسبك</span><h2>${k===1?'هتركب منين؟':'رايح فين؟'}</h2></div><button class="btn g" style="min-height:36px" onclick="closeBk()">إغلاق</button></div><div class="pksearch"><input id="pq" aria-label="بحث عن منطقة أو نقطة تجمع" placeholder="منطقة، مترو، جامعة أو مستشفى…" oninput="pkl(${k})"></div><div id="pkchips"></div><div id="pkl" class="wb pkresults"></div></div>`;pkl(k)}
function pkl(k){const q=($('pq').value||'').trim(),L=k===1?PTS:DROP,rc=(S.rc||[]).filter(x=>x.k===k),A=k===1?(i=>i>=100&&i<226):(i=>i>=29&&i<155),ai=k===1?(i=>i-100):(i=>i-29),nm=k===1?pl1:pl2,ar=k===1?plArea:dlArea,PAR=k===1?PAR_P:PAR_D;
$('pkchips').innerHTML=pkChips(k);
const mp=Object.keys(PAR).map(Number).filter(i=>pkFits(L[i],q)),cat=PK_CAT!=='all';
let h=(!q&&!cat?`<div class="pkcoverage"><b>١٢٦ منطقة · القاهرة والجيزة</b><span>مترو، جامعات، مستشفيات ومعالم معروفة</span></div>`:'')+(k===1&&!q&&!cat?`<button class="btn g" onclick="geoLocate(true);closeBk()">استخدم موقعي الحالي</button>`:'');
const saved=(S.sp||[]).filter(p=>p.k===k&&L[p.i]);if(!q&&!cat&&saved.length)h+='<span class="pksection">أماكنك المحفوظة · على الجهاز ده بس</span>'+saved.map(p=>pkRow(k,p.i,L[p.i],ar(p.i),1)).join('');
if(!q&&!cat&&rc.length)h+='<span class="pksection">آخر اختياراتك</span>'+rc.filter(x=>L[x.i]).map(x=>pkRow(k,x.i,nm(x.i))).join('');
if(q||cat){const seen=new Set(),uniq=mp.filter(i=>{const key=L[i]+'|'+ar(i);if(seen.has(key))return false;seen.add(key);return true});if(uniq.length)h+=`<span class="pksection">نقاط وأماكن · ${uniq.length} نتيجة</span>`+uniq.slice(0,80).map(i=>pkRow(k,i,L[i],ar(i))).join('')+(uniq.length>80?'<span class="mu">فيه نتائج أكتر. اكتب اسم المنطقة عشان تضيق البحث.</span>':'')}
['القاهرة','الجيزة'].forEach(gv=>{const entries=AREAS.map((_,a)=>k===1?100+a:29+a).filter(i=>A(i)&&GOV[L[i]]===gv&&uiPlaceMatch(L[i],q)&&(!cat||(MPS[ai(i)]||[]).some(p=>pkFits(p[0],''))));if(entries.length)h+=`<span class="pksection">${gv} · ${entries.length} منطقة</span>`+entries.map(i=>{const n=(MPS[ai(i)]||[]).filter(p=>!cat||pkFits(p[0],'')).length;return pkRow(k,i,L[i],n+' نقطة ومعلم')}).join('')});
if(!cat){const lm=L.map((n,i)=>[n,i]).filter(x=>x[0]&&(k===1?x[1]<100:x[1]<29)&&uiPlaceMatch(x[0],q));if(lm.length)h+='<span class="pksection">نقاط مشهورة في الجيزة</span>'+lm.map(x=>pkRow(k,x[1],x[0],ar(x[1]))).join('')}
if(k===1)h+=`<button class="btn g" onclick="cpf('p')">+ مش لاقي مكانك؟ ضيف نقطة</button>`;
$('pkl').innerHTML=h||'<div class="pkempty"><b>مش لاقيين المكان ده</b><span>جرّب اسم المنطقة أو معلم قريب، أو غيّر نوع المكان.</span><button class="btn g" onclick="PK_CAT=\'all\';pkl('+k+')">عرض كل الأنواع</button></div>'}
function pkm(k,a){bk=null;PK_CAT='all';PK_AREA=a;const L=k===1?PTS:DROP,aid=k===1?100+a:29+a;$('bk').innerHTML=`<div class="card pkcard"><div class="row"><button class="btn g" style="min-height:36px" onclick="pkr(${k})">رجوع</button><button class="btn g" style="min-height:36px" onclick="closeBk()">إغلاق</button></div><span class="pkcaption">${k===1?'نقطة الركوب':'نقطة الوصول'}</span><h2>${L[aid]}</h2><p class="mu pkdisclaimer">المعالم دي للمقابلة والتنسيق. اتفق مع الكابتن على مكان آمن ومسموح للوقوف خارج البوابات.</p><input id="pmq" placeholder="دور جوه ${L[aid]}…" aria-label="بحث داخل المنطقة" oninput="pkmList(${k},${a})"><div id="pkchips"></div><div id="pml" class="wb pkresults"></div></div>`;pkmList(k,a)}
function pkmList(k,a){const L=k===1?PTS:DROP,aid=k===1?100+a:29+a,PAR=k===1?PAR_P:PAR_D,q=($('pmq').value||'').trim(),pts=(MPS[a]||[]).map((p,j)=>mpid(a,j,k)),leg=Object.keys(PAR).map(Number).filter(i=>i<1000&&PAR[i]===aid);$('pkchips').innerHTML=pkChips(k,a);const seen=new Set(),all=[...pts,...leg].filter(i=>{if(!L[i]||seen.has(L[i]))return false;seen.add(L[i]);return true}),matched=all.filter(i=>pkFits(L[i],q));$('pml').innerHTML=(!q&&PK_CAT==='all'?pkRow(k,aid,'أي نقطة في '+L[aid],'اتفقوا على أقرب مكان مناسب على الطريق',1):'')+`<span class="pksection">${matched.length} نقطة ومعلم ${q?'مطابق للبحث':'للاختيار'}</span>`+matched.map(i=>pkRow(k,i,L[i],PK_CATS.find(c=>c[0]===pkType(L[i]))[1],1)).join('')+(!matched.length?'<div class="pkempty"><b>مفيش نتايج بالنوع ده</b><span>جرّب نوع تاني أو ابحث باسم أقصر.</span></div>':'')}
function pks(k,i,skip){if(k===1)GEO_MANUAL_AT=Date.now();const n=i===''?'':+i,el=$(k===1?'f':'df');if(n!==''&&!el.querySelector('option[value="'+n+'"]')){const o=document.createElement('option');o.value=n;o.textContent=(k===1?PTS:DROP)[n];el.appendChild(o)}el.value=n;if(n!==''){S.rc=[{k,i:n},...(S.rc||[]).filter(x=>!(x.k===k&&x.i===n))].slice(0,6)}rememberRoute();save();closeBk();skl();if(skip!==1&&n!==''){const isA=k===1?(n>=100&&n<226):(n>=29&&n<155);if(isA){const a=k===1?n-100:n-29;if((MPS[a]||[]).length)return pkm(k,a)}}}
function selr(){const cur=$('f').value,ch=new Set([...document.querySelectorAll('.pp:checked')].map(e=>+e.value));$('f').innerHTML='<option value="">كل النقاط</option>'+pgOpts();$('f').value=cur;const lb=i=>`<label><input class="pp" type="checkbox" value="${i}" onchange="ttRender()" ${ch.has(i)?'checked':''}>${PTS[i]}${i>12&&i<100?' ★':''}</label>`;
const areaBlk=a=>{const aid=100+a,pts=(MPS[a]||[]).map((p,j)=>mpid(a,j,1)),leg=Object.keys(PAR_P).map(Number).filter(i=>i<1000&&PAR_P[i]===aid),open=[aid,...pts,...leg].some(i=>ch.has(i));return `<details class="ad"${open?' open':''}><summary>${PTS[aid]}</summary><div class="pts"><label><input class="pp" type="checkbox" value="${aid}" onchange="ttRender()" ${ch.has(aid)?'checked':''}><b>${PTS[aid]} (كل المنطقة)</b></label>${pts.map(lb).join('')}${leg.map(lb).join('')}</div></details>`};
const cust=ord().filter(i=>i>12&&i<100);
$('pp').innerHTML='<span class="mu" style="flex-basis:100%">حدد نقط التجمع اللي بتعدّي عليها في طريقك، والركاب بيركبوا من أقرب نقطة ليهم.</span>'+PGRP.map(g=>{const L=ord().filter(i=>i>=g[1]&&i<g[2]),open=L.some(i=>ch.has(i)||Object.keys(PAR_P).some(x=>PAR_P[x]===i&&ch.has(+x)));return `<details class="ad"${open?' open':''}><summary>${g[0]}</summary>${L.map(i=>areaBlk(i-100)).join('')}</details>`}).join('')+(cust.length?`<details class="ad"${cust.some(i=>ch.has(i))?' open':''}><summary>نقاط مضافة على الطريق</summary><div class="pts">${cust.map(lb).join('')}</div></details>`:'');ttRender()}
function cpf(ctx){bk=null;$('bk').innerHTML=`<div class="card" style="max-height:88vh;overflow:auto"><div class="row"><b>ضيف مكان تاني</b><button class="btn g" style="min-height:36px" onclick="closeBk()">إغلاق</button></div><span class="mu">لو مكانك مش في القايمة، حدده بالنسبة لأقرب نقطة على الطريق. النقطة هتظهر لكل المستخدمين.</span><label for="cpn">اسم المكان</label><input id="cpn" placeholder="مثلاً: أمام مستشفى الهرم"><label for="cpa">بعد أنهي نقطة؟</label><select id="cpa">${ord().filter(i=>i<100).map(i=>`<option value="${i}">${PTS[i]}</option>`).join('')}</select><label for="cpm">بعدها بكام دقيقة؟</label><input id="cpm" type="number" min="1" max="10" value="2"><span class="er" id="cpe" role="alert"></span><button class="btn" onclick="cps('${ctx}')">إضافة</button></div>`}
async function cps(ctx){const n=$('cpn').value.trim(),a=+$('cpa').value,m=+$('cpm').value||0,e=$('cpe');if(!n)return e.textContent='اكتب اسم المكان.';if(PTS.includes(n))return e.textContent='المكان ده موجود بالفعل.';
const nx=ord().find(i=>(OFF[i]||0)>(OFF[a]||0)),gap=nx===undefined?10:(OFF[nx]||0)-(OFF[a]||0);if(gap<2)return e.textContent='مفيش مسافة كافية بعد '+PTS[a]+'. اختار نقطة تانية.';if(m<1||m>=gap)return e.textContent='لازم يكون بين 1 و'+(gap-1)+' دقيقة بعد '+PTS[a]+'.';
const{data,error}=await sb.from('custom_points').insert({name:n,off_minutes:(OFF[a]||0)+m,km:+(((KM[a]||0)+m*14/60).toFixed(1))}).select().single();
if(error)return e.textContent='حصلت مشكلة: '+error.message;
PTS[data.id]=n;OFF[data.id]=data.off_minutes;KM[data.id]=+data.km;selr();closeBk();
if(ctx==='d'){const x=document.querySelector('.pp[value="'+data.id+'"]');if(x){x.checked=true;ttRender()}}else pks(1,String(data.id));toast('اتضافت: '+n+'.')}
function nxr(){const h=new Date().getHours(),b=S.trip||MYBOOKS.find(x=>['accepted','onboard','pending'].includes(x.st));$('gr').textContent=h<12?'صباح الخير':h<18?'مساء الخير':'مساء النور';$('nx').innerHTML=b?`<div class="nx"><div><b>رحلتك الجاية</b><div class="mu">${PTS[b.p]} ${b.t} ← ${DROP[b.dr||0]}${b.wk?' · اشتراك أسبوعي':''}</div></div><button class="btn" onclick="${S.trip?'tab(3)':`trk(${b.rid});`}">تابع</button></div>`:''}

// ---------- auth screens ----------
const EML=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function auErr(m){m=String(m||'');if(/invalid login/i.test(m))return 'الإيميل أو كلمة السر غلط.';if(/already been registered|already registered/i.test(m))return 'الإيميل ده مسجل قبل كده، جرب تسجل دخولك بدل ما تعمل حساب.';if(/at least 6/i.test(m))return 'كلمة السر لازم تكون 6 حروف على الأقل.';if(/valid email|unable to validate/i.test(m))return 'اكتب إيميل صحيح.';if(/rate limit|too many|security purposes/i.test(m))return 'محاولات كتير، استنى دقيقة وجرب تاني.';return 'حصلت مشكلة: '+m}
function auShow(mode){AU_MODE=mode;const e=$('au');e.hidden=false;const inn=mode==='in';
e.innerHTML=`<div class="bh"><div class="bl"><svg viewBox="0 0 48 48" width="34" fill="none" stroke="#fff" stroke-width="4.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 34V19c0-5 7-5 8.8-1l2 5.6c.9 2.4 3.5 2.4 4.4 0l2-5.6c1.8-4 8.8-4 8.8 1v15"/><circle cx="12" cy="34" r="4.6" fill="#fff" stroke="none"/><circle cx="38" cy="34" r="5.2" fill="#A9F2D2" stroke="none"/><circle cx="38" cy="34" r="1.9" fill="#0B4F4A" stroke="none"/></svg></div><b>مشوار معايا</b><small>شارك مشوارك في القاهرة والجيزة، ووفّر</small><div class="tr"><span>سواقين موثّقين</span><span>أرخص بالنص</span><span>نقط تجمع ثابتة</span></div></div><p class="mu" style="max-width:300px;margin:6px 0 0">${inn?'سجل دخولك بالإيميل عشان حسابك يفضل محفوظ على أي جهاز.':'اعمل حساب جديد بالإيميل وكلمة سر. حسابك هيفضل معاك حتى لو مسحت بيانات المتصفح.'}</p><label for="aue">الإيميل</label><input id="aue" type="email" inputmode="email" dir="ltr" placeholder="name@example.com" autocomplete="email"><label for="aup">كلمة السر</label><input id="aup" type="password" dir="ltr" placeholder="٦ حروف على الأقل" autocomplete="${inn?'current-password':'new-password'}"><span class="er" id="aerr" role="alert"></span><button class="btn" style="width:100%;max-width:320px" onclick="auGo()">${inn?'دخول':'إنشاء الحساب'}</button><button class="btn g" style="border:0" onclick="auShow('${inn?'up':'in'}')">${inn?'معندكش حساب؟ اعمل حساب':'عندك حساب؟ سجل دخولك'}</button>${inn?'<button class="btn g" style="border:0" onclick="auReset()">نسيت كلمة السر؟</button>':''}<button class="btn g" style="border:0" onclick="auGuest()">كمّل كضيف من غير حساب</button>`}
async function auGo(){const em=$('aue').value.trim(),pw=$('aup').value,e=$('aerr');if(!EML.test(em))return e.textContent='اكتب إيميل صحيح.';if(pw.length<6)return e.textContent='كلمة السر لازم تكون 6 حروف على الأقل.';e.textContent='ثانية...';
const r=AU_MODE==='in'?await sb.auth.signInWithPassword({email:em,password:pw}):await sb.auth.signUp({email:em,password:pw});
if(r.error)return e.textContent=auErr(r.error.message);
if(AU_MODE==='up'&&!r.data.session)return e.textContent='الحساب اتعمل. افتح إيميلك وأكده لو وصلك لينك، وبعدين سجل دخولك.';
auDone()}
async function auGuest(){const{error}=await sb.auth.signInAnonymously();if(error)return $('aerr').textContent=auErr(error.message);auDone()}
async function auReset(){const em=$('aue').value.trim(),e=$('aerr');if(!EML.test(em))return e.textContent='اكتب إيميلك فوق الأول وبعدين دوس هنا.';const{error}=await sb.auth.resetPasswordForEmail(em,{redirectTo:location.origin+location.pathname});if(error)return e.textContent=auErr(error.message);e.textContent='';toast('بعتنا لينك على إيميلك تعيد منه تعيين كلمة السر.')}
async function auNewPw(){const pw=$('aup').value,e=$('aerr');if(pw.length<6)return e.textContent='كلمة السر لازم تكون 6 حروف على الأقل.';const{error}=await sb.auth.updateUser({password:pw});if(error)return e.textContent=auErr(error.message);$('au').hidden=true;toast('كلمة السر اتغيرت.')}
function auDone(){$('au').hidden=true;if(AU_RES){const r=AU_RES;AU_RES=null;r()}}
async function saveAcct(){const em=$('sve').value.trim(),pw=$('svp').value,e=$('svr');if(!EML.test(em))return e.textContent='اكتب إيميل صحيح.';if(pw.length<6)return e.textContent='كلمة السر لازم تكون 6 حروف على الأقل.';e.textContent='ثانية...';
const{error}=await sb.auth.updateUser({email:em,password:pw});if(error)return e.textContent=auErr(error.message);
ME_ANON=false;ME_EMAIL=em;profR();toast('اتحفظ حسابك. تقدر تدخل بالإيميل ده من أي جهاز.')}

// ---------- onboarding / boot ----------
function obStart(){if(S.ob)return;oi=0;obr();$('ob').hidden=false}
const OBI=['<path d="M12 2v20M17 6.5c0-2-2.2-3.5-5-3.5s-5 1.5-5 3.5 2.2 3.2 5 3.8 5 1.8 5 3.8-2.2 3.4-5 3.4-5-1.4-5-3.4"/>','<path d="M12 21s7-6.2 7-11.5A7 7 0 0 0 5 9.5C5 14.800 12 21 12 21z"/><circle cx="12" cy="9.500" r="2.600"/>','<path d="M12 3l8 3v6c0 4.500-3.400 8-8 9-4.600-1-8-4.500-8-9V6z"/><path d="M8.500 12l2.500 2.500 4.500-5"/>'];
function obr(){const s=OBS[oi];$('ob').innerHTML=`<div class="obi"><svg viewBox="0 0 24 24" aria-hidden="true">${OBI[oi]}</svg></div><h1 style="margin-top:8px">${s[0]}</h1><p class="mu" style="max-width:300px">${s[1]}</p><div class="dots">${OBS.map((_,i)=>`<span class="${i===oi?'on':''}"></span>`).join('')}</div><button class="btn" style="width:100%;max-width:320px" onclick="obn()">${oi===OBS.length-1?'يلا نبدأ':'التالي'}</button><button class="btn g" style="border:0" onclick="obz()">تخطي</button>`}
function obn(){if(oi<OBS.length-1){oi++;obr()}else obz()}
function obz(){$('ob').hidden=true;S.ob=1;save()}
async function reset(){try{await sb.auth.signOut()}catch(e){}localStorage.removeItem(K);location.reload()}
async function poll(){try{await refreshAll(true);await refreshVerification(true);if(!$('v1').hidden||!$('v2').hidden)render();if(S.trip)renderTrip();if(chatBid)loadChat(chatBid).then(()=>{const sh=$('tsh');if(sh)sh.dataset.sig='';renderTrip()})}catch(e){}}
(async function boot(){
  await loadPoints();
  map();selr();
  $('rt').innerHTML=R.map((r,i)=>`<option value="${i}">${r.n}</option>`).join('');
  $('dr').innerHTML=og();$('df').innerHTML='<option value="">كل الأماكن</option>'+og();
  ttRender();cm();
  const{data:{session}}=await sb.auth.getSession();
  if(!session)await new Promise(r=>{AU_RES=r;auShow('in')});
  const{data:{user}}=await sb.auth.getUser();
  ME=user&&user.id;ME_ANON=!!(user&&user.is_anonymous);ME_EMAIL=(user&&user.email)||'';
  if(ME){await loadProfile();await refreshAll(false);await refreshStats();
  try{const{data:ia}=await sb.rpc('is_admin');IS_ADMIN=!!ia;if(IS_ADMIN)$('n6').hidden=false}catch(e){}}
  render();tab(1);routeFromLink();
  setTimeout(()=>{if(GEO_MANUAL_AT)return;const c=S.geo;if(c&&Date.now()-c.at<9e5){geoApply(c.lat,c.lon,true);geoLocate(false,true)}else geoLocate(false,true)},1400);
  setTimeout(()=>{$('sp').style.opacity=0;setTimeout(()=>$('sp').remove(),500)},500);
  setTimeout(obStart,1300);
  setInterval(poll,15000);
  setInterval(updMap,250);
  try{sb.channel('live').on('postgres_changes',{event:'*',schema:'public',table:'bookings'},()=>poll()).on('postgres_changes',{event:'*',schema:'public',table:'rides'},()=>poll()).subscribe()}catch(e){}
})();
